      "ballot_id": "B005",
      "proposed_laureates": [
        "Alexandre Blais",
        "Andreas Wallraff",
        "Robert J. Schoelkopf"
      ],
      "assessment": {
        "nobel_worthiness": "Circuit quantum electrodynamics established a powerful way to couple and control quantum states using superconducting circuits, opening a major experimental field with lasting scientific and technological reach.",
        "attribution": "Blais supplied key theoretical foundations, while Wallraff and Schoelkopf led landmark experimental demonstrations; the theory and experimental realization form a compelling three-person attribution.",
        "maturity": "The framework has been replicated, developed into increasingly capable devices, and sustained for two decades.",
        "uncertainties": [
          "The broader history of superconducting circuits and cavity quantum electrodynamics makes the boundary of the specific contribution important to define."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B008",
      "proposed_laureates": [
        "Franz J. Giessibl",
        "Gerhard Meyer",
        "Leo Gross"
      ],
      "assessment": {
        "nobel_worthiness": "qPlus force microscopy made stable atomic-scale force measurements and chemical contrast possible, providing a broadly useful method for seeing and characterizing individual atoms and bonds.",
        "attribution": "Giessibl developed the qPlus sensor; Meyer and Gross advanced its implementation and demonstrated landmark atomic-resolution imaging. The distinction between invention and later demonstrations should guide credit.",
        "maturity": "The method has been independently used and refined over many years, with clear experimental results across surface science.",
        "uncertainties": [
          "The relative Nobel-level weight of the sensor invention versus later imaging achievements needs careful historical assessment."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B016",
      "proposed_laureates": [
        "Charles L. Kane",
        "Eugene J. Mele",
        "Laurens W. Molenkamp"
      ],
      "assessment": {
        "nobel_worthiness": "The quantum spin Hall prediction and its experimental realization established topological insulators as a major new class of quantum matter.",
        "attribution": "Kane and Mele made the foundational theoretical proposal; Molenkamp's group provided the pivotal experimental demonstration. Later three-dimensional materials brought important additional evidence but need not displace the original work.",
        "maturity": "The central predictions have been confirmed across multiple material systems, and the field has matured substantially.",
        "uncertainties": [
          "The discovery spans theory and several experiments; the precise scope of the prize should distinguish the original quantum spin Hall result from later topological-insulator milestones."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B004",
      "proposed_laureates": [
        "Immanuel Bloch",
        "Juan Ignacio Cirac",
        "Markus Greiner"
      ],
      "assessment": {
        "nobel_worthiness": "Optical-lattice experiments turned ultracold atoms into controllable quantum simulators, enabling direct study of many-body phases that are difficult to access in other systems.",
        "attribution": "Bloch and Greiner led seminal experiments, while Cirac contributed foundational theory for quantum simulation with ultracold atoms.",
        "maturity": "The approach has been replicated, extended to new regimes, and used for increasingly demanding many-body measurements.",
        "uncertainties": [
          "The field's development involved several closely connected groups; the original experimental milestones and theoretical contributions must be separated carefully."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B003",
      "proposed_laureates": [
        "Claudio Pellegrini",
        "Jörg Rossbach",
        "Kwang-Je Kim"
      ],
      "assessment": {
        "nobel_worthiness": "X-ray free-electron lasers opened a new experimental window on ultrafast and nanoscale processes, with broad impact across physics and adjacent sciences.",
        "attribution": "Pellegrini's conceptual work and the accelerator and facility contributions associated with Rossbach and Kim are substantial; the credit must identify the specific original invention rather than later facility leadership.",
        "maturity": "Operational facilities on multiple continents have established the source principle and its scientific value over many years.",
        "uncertainties": [
          "The invention and construction history is distributed across theorists, accelerator physicists, engineers, and large teams, so these three names may not capture the original contributions cleanly."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B007",
      "proposed_laureates": [
        "Albrecht Karle",
        "Francis Halzen"
      ],
      "assessment": {
        "nobel_worthiness": "The detection of high-energy astrophysical neutrinos established a new observational channel for the universe and connected particle physics with astronomy.",
        "attribution": "Halzen was central to the IceCube concept and its realization; Karle made major contributions to the detector and experiment. The discovery relied on a large collaboration.",
        "maturity": "The signal has been established through sustained observations and subsequent events from astrophysical sources.",
        "uncertainties": [
          "A collaboration-scale discovery poses difficult questions about individual credit and the relation between the detector's conception and the first decisive observations."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B026",
      "proposed_laureates": [
        "Alexei Kitaev",
        "Andrew M. Steane",
        "Peter W. Shor"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction supplied the principles that make reliable quantum computation possible despite noise, a profound conceptual and practical advance.",
        "attribution": "Shor and Steane developed early error-correcting codes; Kitaev made foundational contributions to topological approaches. Their distinct advances are significant but span a broad topic.",
        "maturity": "The theory is established and experimental demonstrations have advanced, though large-scale fault-tolerant operation remains an ongoing goal.",
        "uncertainties": [
          "The field includes many essential contributions beyond these three, and its broad development makes a sharply bounded discovery difficult to identify."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B019",
      "proposed_laureates": [
        "Heino Falcke",
        "James M. Moran",
        "Sheperd S. Doeleman"
      ],
      "assessment": {
        "nobel_worthiness": "Event Horizon Telescope imaging provided direct observational evidence of the immediate environment of a black hole and demonstrated extraordinary precision in global radio interferometry.",
        "attribution": "Falcke helped formulate the observing concept, Moran contributed foundational long-baseline interferometry work, and Doeleman led the effort that achieved the image.",
        "maturity": "The image has been independently scrutinized and followed by additional observations, although the field's observational record is still developing.",
        "uncertainties": [
          "The result depended on a large international collaboration and an extended chain of instrumental and computational advances, making individual attribution challenging."
        ]
      }
    }
  ]
